    if (i < vals.length && vals[i] !== -1) {
      curr.right = new Node(vals[i]); q.push(curr.right);
    }
    i++;
  }
  const elements = [];
  const nq = [[root, 0, 0]];
  while (nq.length > 0) {
    const [node, r, c] = nq.shift();
    elements.push({ c, r, v: node.v });
    if (node.left) nq.push([node.left, r + 1, c - 1]);
    if (node.right) nq.push([node.right, r + 1, c + 1]);
  }
  elements.sort((a, b) => a.c !== b.c ? a.c - b.c : (a.r !== b.r ? a.r - b.r : a.v - b.v));
  const colMap = new Map();
  for (const e of elements) {
    if (!colMap.has(e.c)) colMap.set(e.c, []);
    colMap.get(e.c).push(e.v);
  }
  const sortedCols = Array.from(colMap.keys()).sort((a, b) => a - b);
  const res = sortedCols.map(c => colMap.get(c));
  return JSON.stringify(res).replace(/\s+/g, '');
}

