    if not lines: return ""
    class TrieNode:
        def __init__(self): self.children = {}; self.is_end = False
    root = TrieNode()
    res = []
    for line in lines[1:]:
        parts = line.split()
        if not parts: continue
        op = parts[0]
        word = parts[1] if len(parts) > 1 else ""
        if op == "insert":
            curr = root
            for ch in word:
                if ch not in curr.children: curr.children[ch] = TrieNode()
                curr = curr.children[ch]
            curr.is_end = True
        elif op == "search":
            curr = root
            found = True
            for ch in word:
                if ch not in curr.children: found = False; break
                curr = curr.children[ch]
            res.append("true" if found and curr.is_end else "false")
        elif op == "startsWith":
            curr = root
            found = True
            for ch in word:
                if ch not in curr.children: found = False; break
                curr = curr.children[ch]
            res.append("true" if found else "false")
    return "\n".join(res)

