        int nr = r + dr[d], nc = c + dc[d];
        if (nr >= 0 && nr < R && nc >= 0 && nc < C && board[nr][nc] != '#')
            dfs(nr, nc, board, nxt);
    }
    board[r][c] = ch;
}
