void backtrack(int idx, int dots, string cur) {
    if (dots == 4 && idx == S.length()) { res.push_back(cur.substr(0, cur.length() - 1)); return; }
    if (dots > 4 || idx >= S.length()) return;
    for (int len = 1; len <= 3 && idx + len <= S.length(); ++len) {
        string sub = S.substr(idx, len);
        if ((sub.length() > 1 && sub[0] == '0') || stoi(sub) > 255) continue;
        backtrack(idx + len, dots + 1, cur + sub + ".");
    }
}
